const pages = await browser.pages.list();
const ga = pages.filter(x => (x.url || '').includes('analytics.google.com'));
if (!ga.length) { console.log('NO GA4 TAB'); return 'no'; }
const p = await browser.page(ga[ga.length - 1].pageId);
// abrir el selector de cuentas/propiedades
await p.evaluate(() => { const b = Array.from(document.querySelectorAll('button,[role=button]')).find(x => /Todas las cuentas|accounts/i.test(String(x.innerText||''))); if (b) b.click(); });
await sleep(4000);
const raw = await p.evaluate(() => { try { const items = Array.from(document.querySelectorAll('[role=option], [role=menuitem], li, [class*=account], [class*=property]')).map(e => String(e.innerText||'').replace(/\s+/g,' ').trim()).filter(t => t && t.length < 70); return { n: items.length, items: items.slice(0, 45), body: String((document.body&&document.body.textContent)||'').replace(/\s+/g,' ').slice(0, 700) }; } catch (e) { return { err: String(e.message).slice(0,80) } } });
console.log('PICKER ' + JSON.stringify((raw && 'value' in raw) ? raw.value : raw));
return 'ok';
